#!/usr/bin/env python3
"""Read fixed CI bytes without loading/executing the packaged software. Python 3.10+."""
import argparse,collections,csv,hashlib,io,json,tarfile,zipfile
from pathlib import Path,PurePosixPath
from xml.etree import ElementTree as ET
SHA='9138a528872bb9775b9ac05ddb38b5c1de6d7df2'
ARCH={'integration':'44ee180125e155fb7de2e2d06c4d59c4be3b62e514b11d71e9a4aebc23cb1189','wheel':'f8938d72c16806b9475cecdda727bc43965900a8df85d67ba1a05fb8e358dae6','connector':'979a2d14fb1886ead0e4db57b405b077f653b5aeb3c23f5cf8fa1d1bb7ab8ef9'}
h=lambda b:hashlib.sha256(b).hexdigest(); roles={'compact':'原執行 P/E、硬容量、原始請求或測試源快照','connector-address':'改址、原 namespace、終端或憑據','model-connections':'模型連接與任務路由','model-legacy':'舊設定轉換、停用與部分提交','model-usage':'實報欄、授權、時間窗口','provider-presets':'Provider 狀態／設定','search-connection-mode':'搜索模式與連接保存','tool-result-delivery':'完整函式結果、工具 artifact、下一模型觀察'}
def check(b,msg):
 if not b:raise ValueError(msg)
def run(source,out):
 out.mkdir(exist_ok=True,parents=True); tables=[];loc=[];summary={};cases=[];groups=collections.Counter();sources={};wh={};counts=collections.Counter()
 for key,digest in ARCH.items():
  data=(source/f'upstream-{key}.zip').read_bytes();check(h(data)==digest,key+' hash');z=zipfile.ZipFile(io.BytesIO(data));check(z.testzip() is None,key+' crc');
  if key=='integration':
   for path in sorted(z.namelist()):
    b=z.read(path);g=path.partition('/')[0];groups[g]+=1;case='';role=roles.get(g,'pytest JUnit，僅此 CI job，不是全部產品')
    if path.endswith('.json'):
     a=json.loads(b)
     if isinstance(a,dict):case=a.get('nodeid','');
     if case and g=='compact':
      check(a['source_revision']==SHA,'source drift');steps=[r.get('kind') for r in a['requests']];keys=[]
      for ent in a['source_files']:
       path2=str(PurePosixPath(path).parent/ent['snapshot']);raw=z.read(path2);check(h(raw)==ent['sha256'],path2);sources[ent['path']]=h(raw)
      if a.get('call_id') and case.endswith('[known-finish]'):
       check(steps==['normal','public_compact','normal'],case);wire=a['wire_requests'][-1]['messages'];keys=[r.get('tool_call_id') for r in wire if r.get('role')=='tool'];check(a['call_id'] in keys,case+' missing tool');receipt=json.loads(next(r['content'] for r in wire if r.get('tool_call_id')==a['call_id']));check(receipt['ok'] and receipt['data']['status']=='succeeded',case);events={r['id']:r for r in a['events']};check(all(events[p['event_id']]['content']==p['delivered_text'] and events[p['event_id']]['direction']=='outbound' for p in receipt['data']['parts']),case+' mismatched delivery');summary['checked_public_then_normal']={'call':a['call_id'],'original_parts':len(receipt['data']['parts']),'steps':steps,'evidence_path':path}
      cases.append(dict(case=case,sequence=steps,snapshot_count=len(a['source_files'])))
     if path=='model-usage/known-coverage-cache.json':
      s=a['summary'];check((s['invocations'],s['failures'],s['total_tokens'],s['coverage']['total_tokens'])==(6,1,1044,4),'usage');check((s['cache_read']['cached_prompt_tokens'],s['cache_read']['prompt_tokens'])==(47,110),'ratio');summary['offline_usage_fixture']=s
     if path=='model-legacy/retirement-partial.json':check(a['partial']['partial'] and not a['partial']['ok'] and a['retry']['ok'] and a['user_edit_preserved'],'partial migration');summary['offline_config_fixture']=a
    if path.endswith('.xml'):
     n=ET.fromstring(b);summary['CI_junit']=[{k:s.attrib[k] for k in ('tests','errors','failures','skipped') if k in s.attrib} for s in n.iter('testsuite')]
    tables.append((key,path,len(b),h(b),role,case));
   continue
  if key=='wheel':
   w=zipfile.ZipFile(io.BytesIO(z.read(next(n for n in z.namelist() if n.endswith('.whl'))))); items=[('src/'+n,w.read(n)) for n in w.namelist() if n.endswith('.py')];
  else:
   tar=tarfile.open(fileobj=io.BytesIO(z.read(next(n for n in z.namelist() if n.endswith('.tar.gz')))),mode='r:gz');items=[('packages/yuki-agent-connector/'+m.name.split('/',1)[1],tar.extractfile(m).read()) for m in tar.getmembers() if m.isfile() and m.name.endswith('.py')];
  for path,b in sorted(items):
   text=b.decode('utf-8');c=('generated' if any(a in '\n'.join(text.splitlines()[:8]).lower() for a in ('generated by the protocol buffer compiler','automatically generated by','do not edit this file!')) or path.endswith('_pb2.py') else 'connector tests' if '/tests/' in path else 'connector scripts' if '/scripts/' in path else 'connector runtime' if key=='connector' else 'plugin SDK' if path.startswith('src/yuki_plugin_sdk/') else 'host runtime');lines=b.count(b'\n')+(bool(b) and not b.endswith(b'\n'));loc.append((c,path,lines,h(b)));counts[(c,'files')]+=1;counts[(c,'lines')]+=lines
 for name,header,rows in [('ci-members.tsv',['archive','path','bytes','sha256','purpose','nodeid'],tables),('package-loc.tsv',['class','source_path','physical_lines','sha256'],loc)]:
  with (out/name).open('w',encoding='utf8',newline='') as f:w=csv.writer(f,delimiter='\t',lineterminator='\n');w.writerow(header);w.writerows(rows)
 summary.update(ci_sha=SHA,archive_hashes=ARCH,integration_members=dict(groups),compact_cases=cases,distinct_source_snapshots=sources,package_only_loc={c:{t:counts[c,t] for t in ['files','lines']} for c in sorted({c for c,k in counts})},whole_repo_loc=None,whole_repo_doc_count=None,product_e2e_this_audit=False);return summary
if __name__=='__main__':
 p=argparse.ArgumentParser(); p.add_argument('--archives',type=Path,default=Path(__file__).parent/'evidence');p.add_argument('--out',type=Path,default=Path(__file__).parent/'results');a=p.parse_args();r=run(a.archives,a.out);(a.out/'ci-source-proof.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps({k:r[k] for k in ('CI_junit','package_only_loc','checked_public_then_normal','integration_members')},ensure_ascii=False,indent=2))
